Proceso VerificarPalindromo
    Definir palabra Como Cadena;
    Definir i Como Entero;
    Definir longitud Como Entero;
    Definir esPalindromo Como Entero;
    Leer palabra;
    longitud <- Longitud(palabra);
    esPalindromo <- 1;
    Para i <- 0 Hasta longitud Div 2 - 1 Con Paso 1 Hacer
        Si CaracterEn(palabra, i) <> CaracterEn(palabra, longitud - 1 - i) Entonces
            esPalindromo <- 0;
        FinSi
    FinPara
    Escribir esPalindromo;
FinProceso
